package java.text;
import java.util.Locale;
public class DecimalFormatSymbols implements java.io.Serializable,Cloneable {private char decimal='.',grouping=',',percent='%',minus='-',zero='0';private String currency="$",infinity="∞",nan="NaN";public DecimalFormatSymbols(){}public DecimalFormatSymbols(Locale l){}public static DecimalFormatSymbols getInstance(){return new DecimalFormatSymbols();}public static DecimalFormatSymbols getInstance(Locale l){return new DecimalFormatSymbols(l);}public char getDecimalSeparator(){return decimal;}public void setDecimalSeparator(char c){decimal=c;}public char getGroupingSeparator(){return grouping;}public void setGroupingSeparator(char c){grouping=c;}public char getPercent(){return percent;}public void setPercent(char c){percent=c;}public char getMinusSign(){return minus;}public void setMinusSign(char c){minus=c;}public char getZeroDigit(){return zero;}public void setZeroDigit(char c){zero=c;}public String getCurrencySymbol(){return currency;}public void setCurrencySymbol(String s){currency=s;}public String getInfinity(){return infinity;}public String getNaNaN(){return nan;}public String getNaN(){return nan;}}
